drills.solution:
const WEEK_MS = 7 * 24 * 60 * 60 * 1000;

export function createInvite(deps, input) {
  const now = deps.clock.now();
  const invite = {
    id: deps.newId(),
    email: input.email.trim().toLowerCase(),
    tenantId: input.tenantId,
    createdAt: new Date(now).toISOString(),
    expiresAt: new Date(now + WEEK_MS).toISOString(),
  };
  deps.store.insert(invite);
  return invite;
}

export function isExpired(deps, invite) {
  return deps.clock.now() >= Date.parse(invite.expiresAt);
}

tests.code:
assert.equal(typeof mod.createInvite, 'function', 'export createInvite');
const deps = { clock: { now: () => Date.UTC(2030, 0, 1) }, newId: () => 'inv_1', store: { insert() {} } };
const invite = mod.createInvite(deps, { email: 'ada@example.com', tenantId: 't1' });
assert.equal(invite.createdAt, '2030-01-01T00:00:00.000Z');
assert.equal(invite.expiresAt, '2030-01-08T00:00:00.000Z');

let n = 0;
const deps = { clock: { now: () => 0 }, newId: () => 'inv_' + ++n, store: { insert() {} } };
assert.equal(mod.createInvite(deps, { email: 'a@x.io', tenantId: 't1' }).id, 'inv_1');
assert.equal(mod.createInvite(deps, { email: 'b@x.io', tenantId: 't1' }).id, 'inv_2');

let t = Date.UTC(2030, 5, 30, 23, 59, 59, 990);
const deps = { clock: { now: () => (t += 5) }, newId: () => 'inv_9', store: { insert() {} } };
const invite = mod.createInvite(deps, { email: 'ada@example.com', tenantId: 't1' });
assert.equal(invite.createdAt, '2030-06-30T23:59:59.995Z', 'createdAt is the first reading');
assert.equal(Date.parse(invite.expiresAt) - Date.parse(invite.createdAt), 7 * 24 * 60 * 60 * 1000, 'both timestamps must come from one reading of the clock');

const inserted = [];
const deps = { clock: { now: () => Date.UTC(2030, 0, 1) }, newId: () => 'inv_1', store: { insert: (x) => inserted.push(x) } };
const invite = mod.createInvite(deps, { email: '  Ada@Example.COM ', tenantId: 't7' });
assert.equal(inserted.length, 1);
assert.deepEqual(inserted[0], invite);
assert.deepEqual(invite, { id: 'inv_1', email: 'ada@example.com', tenantId: 't7', createdAt: '2030-01-01T00:00:00.000Z', expiresAt: '2030-01-08T00:00:00.000Z' });

assert.equal(typeof mod.isExpired, 'function', 'export isExpired');
const invite = { id: 'inv_1', expiresAt: '2030-01-08T00:00:00.000Z' };
const at = (ms) => ({ clock: { now: () => ms } });
const expiry = Date.UTC(2030, 0, 8);
assert.equal(mod.isExpired(at(expiry - 1), invite), false, 'one millisecond before expiry');
assert.equal(mod.isExpired(at(expiry), invite), true, 'at the expiry instant');
assert.equal(mod.isExpired(at(expiry + 1), invite), true);

drills.explanation:
Read each dependency from `deps`, and the clock exactly once:

```js
const now = deps.clock.now();
const invite = {
  id: deps.newId(),
  email: input.email.trim().toLowerCase(),
  tenantId: input.tenantId,
  createdAt: new Date(now).toISOString(),
  expiresAt: new Date(now + WEEK_MS).toISOString(),
};
```

and compare with `>=` in `isExpired`. Seven days in milliseconds is safe here because ISO strings are UTC; there is no daylight-saving shift.

The tests catch a plausible-wrong refactor that injects the clock but still reads it twice: on a real or advancing clock the two readings differ, so `expiresAt` is not exactly a week after `createdAt` (the fake clock in the trap test advances 5 ms per reading). Keeping the legacy `>` makes an invite still valid at its exact expiry instant.

drills.instructions:
**Interview prompt.** "Nobody dares touch `shippingFee`: it has no tests. Before we refactor it, write the cases that pin what it does today."

**Why it matters.** A characterization suite records current behaviour, odd results included, so a refactor can prove it changed nothing. Its strength is measured with mutants: small, plausible edits to the code that a good suite notices.

The legacy function (it is also in the starter, so you can call it):

```js
function shippingFee({ subtotal, weightKg, express, country }) {
  let fee = subtotal >= 50 ? 0 : 7;
  if (weightKg > 10) fee += Math.ceil(weightKg - 10) * 2;
  if (express) fee *= 2;
  if (country !== 'US') fee += 15;
  return fee;
}
```

**Your task.** Export `cases`: an array of 1 to 8 entries `{ order, expected }`, where `order` is `{ subtotal, weightKg, express, country }` (two numbers, a boolean and a string) and `expected` is a number.
- every `expected` must equal what the legacy function returns for its `order`, even where that looks wrong
- the grader runs your cases against three planted mutants of the function: one changes a comparison, one changes a rounding, and one swaps the order of two steps; every mutant must disagree with at least one of your cases

**Worked example.** `{ order: { subtotal: 20, weightKg: 1, express: false, country: 'US' }, expected: 7 }` is a valid case, but it kills none of the mutants.

