// Legacy code: do not change it. Pin what it does today.
function shippingFee({ subtotal, weightKg, express, country }) {
  let fee = subtotal >= 50 ? 0 : 7;
  if (weightKg > 10) fee += Math.ceil(weightKg - 10) * 2;
  if (express) fee *= 2;
  if (country !== 'US') fee += 15;
  return fee;
}

const orders = [
  { subtotal: 50, weightKg: 1, express: false, country: 'US' },
  { subtotal: 49.99, weightKg: 1, express: false, country: 'US' },
  { subtotal: 20, weightKg: 10.5, express: false, country: 'US' },
  { subtotal: 20, weightKg: 1, express: true, country: 'DE' },
  { subtotal: 60, weightKg: 1, express: true, country: 'US' },
];

export const cases = orders.map((order) => ({ order, expected: shippingFee(order) }));

tests.code:
assert.ok(Array.isArray(mod.cases), 'export an array named cases');
assert.ok(mod.cases.length >= 1 && mod.cases.length <= 8, 'between 1 and 8 cases, got ' + mod.cases.length);
for (const c of mod.cases) {
  const o = c.order;
  assert.ok(o && typeof o.subtotal === 'number' && typeof o.weightKg === 'number' && typeof o.express === 'boolean' && typeof o.country === 'string', 'bad order: ' + JSON.stringify(o));
  assert.equal(typeof c.expected, 'number', 'expected must be a number');
}

const legacy = ({ subtotal, weightKg, express, country }) => {
  let fee = subtotal >= 50 ? 0 : 7;
  if (weightKg > 10) fee += Math.ceil(weightKg - 10) * 2;
  if (express) fee *= 2;
  if (country !== 'US') fee += 15;
  return fee;
};
assert.ok(Array.isArray(mod.cases) && mod.cases.length > 0, 'export a non-empty cases array');
for (const c of mod.cases) assert.equal(c.expected, legacy(c.order), 'legacy returns ' + legacy(c.order) + ' for ' + JSON.stringify(c.order));

const mutant = ({ subtotal, weightKg, express, country }) => {
  let fee = subtotal > 50 ? 0 : 7;
  if (weightKg > 10) fee += Math.ceil(weightKg - 10) * 2;
  if (express) fee *= 2;
  if (country !== 'US') fee += 15;
  return fee;
};
assert.ok(Array.isArray(mod.cases), 'export cases');
assert.ok(mod.cases.some((c) => mutant(c.order) !== c.expected), 'no case notices when >= 50 becomes > 50');

const mutant = ({ subtotal, weightKg, express, country }) => {
  let fee = subtotal >= 50 ? 0 : 7;
  if (weightKg > 10) fee += Math.floor(weightKg - 10) * 2;
  if (express) fee *= 2;
  if (country !== 'US') fee += 15;
  return fee;
};
assert.ok(Array.isArray(mod.cases), 'export cases');
assert.ok(mod.cases.some((c) => mutant(c.order) !== c.expected), 'no case notices when ceil becomes floor');

const mutant = ({ subtotal, weightKg, express, country }) => {
  let fee = subtotal >= 50 ? 0 : 7;
  if (weightKg > 10) fee += Math.ceil(weightKg - 10) * 2;
  if (country !== 'US') fee += 15;
  if (express) fee *= 2;
  return fee;
};
assert.ok(Array.isArray(mod.cases), 'export cases');
assert.ok(mod.cases.some((c) => mutant(c.order) !== c.expected), 'no case notices when the international surcharge moves before the express doubling');

