drills.solution:
const levelFor = (status) => (status >= 500 ? 'error' : status >= 400 ? 'warn' : 'info');

export function logRequest(ctx) {
  const entry = {
    level: levelFor(ctx.status),
    requestId: ctx.requestId,
    tenantId: ctx.tenantId ?? null,
    userId: ctx.user?.id ?? null,
    method: ctx.method,
    path: ctx.url.split('?')[0],
    status: ctx.status,
    durationMs: ctx.endedAt - ctx.startedAt,
  };
  if (ctx.error) entry.error = String(ctx.error.message ?? ctx.error);
  return JSON.stringify(entry);
}

tests.code:
assert.equal(typeof mod.logRequest, 'function', 'export logRequest');
const line = mod.logRequest({
  requestId: 'r1', tenantId: 't1', user: { id: 'u5', email: 'ada@example.com' }, method: 'GET', url: '/orders/7?expand=items',
  status: 200, startedAt: 1000, endedAt: 1042, headers: { 'user-agent': 'curl/8' }, body: undefined,
});
assert.equal(typeof line, 'string');
assert.ok(!line.includes('\n'), 'one line');
assert.deepEqual(JSON.parse(line), { level: 'info', requestId: 'r1', tenantId: 't1', userId: 'u5', method: 'GET', path: '/orders/7', status: 200, durationMs: 42 });

const base = { requestId: 'r2', tenantId: 't1', user: { id: 'u1' }, method: 'GET', url: '/health', status: 200, headers: {}, body: undefined };
assert.equal(JSON.parse(mod.logRequest({ ...base, startedAt: 5000, endedAt: 5250 })).durationMs, 250);
const zero = JSON.parse(mod.logRequest({ ...base, startedAt: 7000, endedAt: 7000 }));
assert.ok(Object.hasOwn(zero, 'durationMs'), 'a 0 ms request still has durationMs');
assert.equal(zero.durationMs, 0);

const line = mod.logRequest({
  requestId: 'r3', tenantId: 't9', user: { id: 'u2', email: 'bob@example.com', password: 'hunter2' }, method: 'POST', url: '/login',
  status: 401, startedAt: 0, endedAt: 12,
  headers: { authorization: 'Bearer s3cr3t-token', cookie: 'sid=abc123session', 'user-agent': 'x' },
  body: { email: 'bob@example.com', password: 'hunter2', cardNumber: '4111111111111111' },
});
for (const secret of ['hunter2', 's3cr3t-token', 'abc123session', '4111111111111111', 'bob@example.com']) {
  assert.ok(!line.includes(secret), 'leaked ' + secret + ' in ' + line);
}
assert.deepEqual(Object.keys(JSON.parse(line)).sort(), ['durationMs', 'level', 'method', 'path', 'requestId', 'status', 'tenantId', 'userId']);

const line = mod.logRequest({
  requestId: 'r4', tenantId: 't1', method: 'GET', url: '/password-reset?token=t0k3n-xyz&email=a%40b.c',
  status: 302, startedAt: 0, endedAt: 3, headers: {}, body: undefined,
});
assert.equal(JSON.parse(line).path, '/password-reset');
assert.ok(!line.includes('t0k3n-xyz'), 'the reset token leaked into the log');

const base = { requestId: 'r5', tenantId: 't1', user: { id: 'u1' }, method: 'PUT', url: '/orders/1', startedAt: 0, endedAt: 9, headers: {}, body: undefined };
const failed = JSON.parse(mod.logRequest({ ...base, status: 503, error: new Error('db down') }));
assert.equal(failed.level, 'error');
assert.equal(failed.error, 'db down');
const missing = JSON.parse(mod.logRequest({ ...base, status: 404 }));
assert.equal(missing.level, 'warn');
assert.ok(!Object.hasOwn(missing, 'error'), 'no error key without an error');
assert.equal(JSON.parse(mod.logRequest({ ...base, status: 204 })).level, 'info');
assert.equal(JSON.parse(mod.logRequest({ ...base, status: 499 })).level, 'warn');

const entry = JSON.parse(mod.logRequest({ requestId: 'r6', method: 'GET', url: '/public', status: 200, startedAt: 0, endedAt: 1, headers: {}, body: undefined }));
assert.ok(Object.hasOwn(entry, 'tenantId') && Object.hasOwn(entry, 'userId'), 'both keys present');
assert.equal(entry.tenantId, null);
assert.equal(entry.userId, null);
